	private void addInstances(String type, int count) {
		IRI typeIri = vf.createIRI(NS + type);
		try (RepositoryConnection connection = store.getConnection()) {
			for (int index = 0; index < count; index++) {
				connection.add(vf.createIRI(NS + type.toLowerCase() + "/" + index), RDF.TYPE, typeIri);
			}
		}
	}

	private void addToGraph(String graph, int statements) {
		Resource context = graph == null ? null : vf.createIRI(NS + graph);
		try (RepositoryConnection connection = store.getConnection()) {
			for (int index = 0; index < statements; index++) {
				connection.add(vf.createIRI(NS + "s" + index), vf.createIRI(NS + "p"),
						vf.createLiteral(String.valueOf(graph) + index), context);
			}
		}
	}

